model ThermalTank "First-order lumped-capacitance heated liquid tank"
  parameter Real C(unit="J/K") = 41840.0 "Thermal capacitance of 10 kg water";
  parameter Real R(unit="K/W") = 0.08 "Thermal resistance to ambient";
  parameter Real T_amb(unit="K") = 293.15 "Ambient temperature (20 degC)";
  parameter Real Q_heater(unit="W") = 1200.0 "Electric immersion heater power";
  parameter Real T0(unit="K") = 293.15 "Initial tank temperature";

  Real T(unit="K", start=T0, fixed=true) "Bulk liquid temperature";
  Real Q_loss(unit="W") "Convective heat loss to environment";
  Real T_degC(unit="degC") "Tank temperature in Celsius";

equation
  Q_loss = (T - T_amb) / R;
  C * der(T) = Q_heater - Q_loss;
  T_degC = T - 273.15;

  annotation(
    experiment(StartTime=0, StopTime=6000, Tolerance=1e-6),
    Documentation(info="<html><p>First-order thermal tank model with steady-state temperature T_ss = T_amb + R*Q_heater.</p></html>")
  );
end ThermalTank;

model RLCResonantCircuit "Underdamped series RLC resonant circuit"
  parameter Real R(unit="Ohm") = 4.0 "Series resistance";
  parameter Real L(unit="H") = 0.025 "Series inductance";
  parameter Real C(unit="F") = 100e-6 "Series capacitance";
  parameter Real V_amp(unit="V") = 24.0 "AC source amplitude";
  parameter Real f_drive(unit="Hz") = 100.66 "Driving frequency near resonance";
  constant Real pi = 3.141592653589793;

  Real v_src(unit="V") "Source voltage";
  Real i(unit="A", start=0.0, fixed=true) "Series loop current";
  Real v_C(unit="V", start=0.0, fixed=true) "Capacitor voltage";
  Real v_L(unit="V") "Inductor voltage";
  Real v_R(unit="V") "Resistor voltage";
  Real E_stored(unit="J") "Total electromagnetic stored energy";

equation
  v_src = V_amp * sin(2.0 * pi * f_drive * time);
  v_R = R * i;
  v_L = L * der(i);
  C * der(v_C) = i;
  v_src = v_R + v_L + v_C;
  E_stored = 0.5 * L * i * i + 0.5 * C * v_C * v_C;

  annotation(
    experiment(StartTime=0, StopTime=0.15, Tolerance=1e-6)
  );
end RLCResonantCircuit;

model ChuaOscillator "Chua's double-scroll chaotic electronic oscillator"
  parameter Real alpha = 15.6 "Capacitance ratio C2/C1";
  parameter Real beta = 28.0 "Normalized inductance parameter";
  parameter Real m0 = -1.143 "Inner slope of piecewise-linear Chua diode";
  parameter Real m1 = -0.714 "Outer slope of piecewise-linear Chua diode";

  Real x(start=0.7, fixed=true) "Normalized voltage across C1";
  Real y(start=0.0, fixed=true) "Normalized voltage across C2";
  Real z(start=0.0, fixed=true) "Normalized inductor current";
  Real h "Chua diode nonlinear current characteristic";

equation
  h = m1 * x + 0.5 * (m0 - m1) * (abs(x + 1.0) - abs(x - 1.0));
  der(x) = alpha * (y - x - h);
  der(y) = x - y + z;
  der(z) = -beta * y;

  annotation(
    experiment(StartTime=0, StopTime=60, Tolerance=1e-7)
  );
end ChuaOscillator;

model EVBatteryPack "Coupled 800V EV traction battery electro-thermal pack model"
  parameter Integer n_series = 216 "Cells in series (nominal 800V)";
  parameter Integer n_parallel = 2 "Strings in parallel";
  parameter Real Q_cell(unit="A.s") = 50.0 * 3600.0 "Cell capacity (50 Ah)";
  parameter Real R0_ref(unit="Ohm") = 0.0018 "Ohmic resistance per cell at 25 degC";
  parameter Real R1(unit="Ohm") = 0.0012 "Fast RC polarization resistance";
  parameter Real C1(unit="F") = 2500.0 "Fast RC polarization capacitance";
  parameter Real C_th(unit="J/K") = 380000.0 "Pack thermal mass";
  parameter Real hA_cool(unit="W/K") = 180.0 "Liquid cooling plate conductance";
  parameter Real T_cool(unit="K") = 298.15 "Coolant inlet temperature";
  parameter Real P_load(unit="W") = 150000.0 "Constant traction discharge power (150 kW)";

  Real soc(start=0.85, fixed=true) "Pack state of charge [0..1]";
  Real v_rc1(unit="V", start=0.0, fixed=true) "Cell RC polarization voltage";
  Real T_pack(unit="K", start=298.15, fixed=true) "Pack core temperature";
  Real V_oc_cell(unit="V") "Open-circuit voltage per cell";
  Real R0_cell(unit="Ohm") "Temperature-dependent ohmic resistance";
  Real I_pack(unit="A") "Pack discharge current";
  Real I_cell(unit="A") "Per-cell discharge current";
  Real V_pack(unit="V") "Pack terminal voltage";
  Real Q_gen(unit="W") "Total Joule heat generation";

equation
  V_oc_cell = 3.25 + 0.85 * soc + 0.08 * soc * soc;
  R0_cell = R0_ref * (1.0 + 0.004 * (298.15 - T_pack));
  I_cell = I_pack / n_parallel;
  C1 * der(v_rc1) = I_cell - v_rc1 / R1;
  V_pack = n_series * (V_oc_cell - I_cell * R0_cell - v_rc1);
  P_load = V_pack * I_pack;
  der(soc) = -I_cell / Q_cell;
  Q_gen = n_series * n_parallel * (I_cell * I_cell * R0_cell + v_rc1 * v_rc1 / R1);
  C_th * der(T_pack) = Q_gen - hA_cool * (T_pack - T_cool);

  annotation(
    experiment(StartTime=0, StopTime=900, Tolerance=1e-6)
  );
end EVBatteryPack;

